CREATE TABLE WF_AGENT (
  ID VARCHAR2(64 ) NOT NULL ,
  PROCESS_DEF_NAME VARCHAR2(255 ) ,
  PROCESS_DEF_ID VARCHAR2(64 ) ,
  TASK_DEF_KEY VARCHAR2(200 ) ,
  START_DATE DATE ,
  END_DATE DATE ,
  AGENT_USER VARCHAR2(64 ) ,
  TRUST_USER VARCHAR2(64 ) ,
  TYPE VARCHAR2(64 ) ,
  REMARKS VARCHAR2(255 ) ,
  EFFECT_IND VARCHAR2(255 ) ,
  TENANT_ID VARCHAR2(64 ) ,
  CREATE_BY VARCHAR2(64 ) ,
  AGENT_TYPE VARCHAR2(20 ) ,
  CREATE_DATE DATE
);

ALTER TABLE WF_AGENT ADD CONSTRAINT SYS_C0041284 PRIMARY KEY (ID);

ALTER TABLE WF_AGENT ADD TRUST_TYPE VARCHAR2(10);

